-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Cardiovascular in elderly — isolated systolic HTN, orthostatic hypotension, HFpEF - Part 4 (301-400)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-cardiovascular' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-cardiovascular not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 94-year-old female named Jean with suspected heart failure has a BNP level of 320 pg/mL. Her LVEF is 68%. A colleague states that the BNP is ''not high enough'' to diagnose heart failure. Which of the following is the most accurate interpretation?', '["BNP levels are always higher in HFpEF than in HFrEF because diastolic dysfunction generates more myocardial wall stress than systolic dysfunction", "A BNP below 500 pg/mL always excludes heart failure regardless of the clinical presentation, ejection fraction, or echocardiographic findings", "Natriuretic peptide levels in HFpEF are often lower than in HFrEF because the LV is smaller (concentric hypertrophy) and wall stress is less than in a dilated, volume-overloaded ventricle; a BNP > 35 pg/mL or NT-proBNP > 125 pg/mL still supports the diagnosis in the correct clinical context, especially when combined with echocardiographic evidence of diastolic dysfunction", "BNP is only elevated in HFrEF and has no diagnostic utility in HFpEF; the test should not be ordered if LVEF is >= 50%", "Obesity does not affect BNP levels, and the standard cutoffs apply universally regardless of body mass index"]'::jsonb, 2, '**Natriuretic peptide levels in HFpEF are characteristically LOWER than in HFrEF.** Reasons: (1) BNP/NT-proBNP secretion is proportional to **myocardial wall stress** (LaPlace''s law: wall stress = [pressure × radius] / [2 × wall thickness]). In HFpEF, the LV has **concentric hypertrophy** (thick walls, small cavity), so wall stress is relatively low despite high filling pressures. In HFrEF, the LV is dilated (large radius, thin walls), generating much higher wall stress. (2) **Obesity** (common in HFpEF) independently suppresses BNP levels (adipose tissue expresses neprilysin, which degrades BNP). Therefore, **normal or mildly elevated BNP does NOT exclude HFpEF**, and clinicians must integrate clinical presentation, echocardiography, and biomarkers. (Ref: 2022 AHA/ACC/HFSA HF Guidelines; Hazzard''s Ch. 38; Maisel AS et al., JACC 2017)'),
    (v_topic_id, 'A 78-year-old female named Rose with suspected heart failure has a BNP level of 420 pg/mL. Her LVEF is 60%. A colleague states that the BNP is ''not high enough'' to diagnose heart failure. Which of the following is the most accurate interpretation?', '["Natriuretic peptide levels in HFpEF are often lower than in HFrEF because the LV is smaller (concentric hypertrophy) and wall stress is less than in a dilated, volume-overloaded ventricle; a BNP > 35 pg/mL or NT-proBNP > 125 pg/mL still supports the diagnosis in the correct clinical context, especially when combined with echocardiographic evidence of diastolic dysfunction", "Obesity does not affect BNP levels, and the standard cutoffs apply universally regardless of body mass index", "A BNP below 500 pg/mL always excludes heart failure regardless of the clinical presentation, ejection fraction, or echocardiographic findings", "BNP is only elevated in HFrEF and has no diagnostic utility in HFpEF; the test should not be ordered if LVEF is >= 50%", "BNP levels are always higher in HFpEF than in HFrEF because diastolic dysfunction generates more myocardial wall stress than systolic dysfunction"]'::jsonb, 0, '**Natriuretic peptide levels in HFpEF are characteristically LOWER than in HFrEF.** Reasons: (1) BNP/NT-proBNP secretion is proportional to **myocardial wall stress** (LaPlace''s law: wall stress = [pressure × radius] / [2 × wall thickness]). In HFpEF, the LV has **concentric hypertrophy** (thick walls, small cavity), so wall stress is relatively low despite high filling pressures. In HFrEF, the LV is dilated (large radius, thin walls), generating much higher wall stress. (2) **Obesity** (common in HFpEF) independently suppresses BNP levels (adipose tissue expresses neprilysin, which degrades BNP). Therefore, **normal or mildly elevated BNP does NOT exclude HFpEF**, and clinicians must integrate clinical presentation, echocardiography, and biomarkers. (Ref: 2022 AHA/ACC/HFSA HF Guidelines; Hazzard''s Ch. 38; Maisel AS et al., JACC 2017)'),
